// Command pyclient generates the Python client's models (clients/python/src/clearance_client/_models.py) from the
// core's contract (contract/clearance-core.json), and its version (_version.py) from the clearance release
// version (the repository's VERSION file, internal/release). It is deterministic: the same inputs give the same bytes, and its test fails when the committed files
// differ from a fresh generation.
//
//	go run ./tools/pyclient            # from the module root: rewrite the generated files
//	go run ./tools/pyclient -check     # exit 1 when they are stale
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/jfillman/clearance/internal/release"
)

// Paths, relative to the module root.
const (
	ContractPath = "contract/clearance-core.json"
	ModelsPath   = "clients/python/src/clearance_client/_models.py"
	VersionPath  = "clients/python/src/clearance_client/_version.py"
)

func main() {
	root := flag.String("root", ".", "the module root")
	check := flag.Bool("check", false, "only check that the generated files are current")
	flag.Parse()
	files, err := GenerateFrom(*root)
	if err != nil {
		fmt.Fprintln(os.Stderr, "pyclient:", err)
		os.Exit(2)
	}
	stale := false
	for _, name := range sortedKeys(files) {
		path := filepath.Join(*root, name)
		if *check {
			cur, err := os.ReadFile(path)
			if err != nil || !bytes.Equal(cur, files[name]) {
				fmt.Fprintf(os.Stderr, "pyclient: %s is stale: run go run ./tools/pyclient\n", name)
				stale = true
			}
			continue
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil {
			fmt.Fprintln(os.Stderr, "pyclient:", err)
			os.Exit(2)
		}
	}
	if stale {
		os.Exit(1)
	}
}

// GenerateFrom reads the contract and the version under root and returns the generated files by path.
func GenerateFrom(root string) (map[string][]byte, error) {
	contract, err := os.ReadFile(filepath.Join(root, ContractPath))
	if err != nil {
		return nil, err
	}
	version, err := release.Version(root)
	if err != nil {
		return nil, err
	}
	models, err := Models(contract)
	if err != nil {
		return nil, err
	}
	return map[string][]byte{ModelsPath: models, VersionPath: Version(version)}, nil
}

// Version is _version.py.
func Version(v string) []byte {
	return []byte(header + "\n" + `"""The clearance release this client was generated for (the tag v` + v + `)."""` + "\n\n" +
		"__version__ = " + strconv.Quote(v) + "\n")
}

const header = "# Code generated by tools/pyclient from the clearance repo; DO NOT EDIT."

// -- the contract --------------------------------------------------------------------------------------------------

type schema map[string]any

type doc struct {
	Info struct {
		Version string `json:"version"`
	} `json:"info"`
	Paths      map[string]map[string]operation `json:"paths"`
	Components struct {
		Schemas map[string]schema `json:"schemas"`
	} `json:"components"`
	RecordKinds []string `json:"x-clearance-record-kinds"`
}

type operation struct {
	OperationID string `json:"operationId"`
	Auth        string `json:"x-clearance-auth"`
	MaxBody     int64  `json:"x-clearance-max-body"`
	RequestBody *struct {
		Content map[string]struct {
			Schema schema `json:"schema"`
		} `json:"content"`
	} `json:"requestBody"`
	Responses map[string]struct {
		Content map[string]struct {
			Schema schema `json:"schema"`
		} `json:"content"`
	} `json:"responses"`
}

// class is one generated dataclass.
type class struct {
	name, source string // Python name, contract name ("" for an inline schema)
	strict       bool   // additionalProperties false: a request type
	fields       []pyField
}

type pyField struct {
	json, attr, typ, desc string
	required              bool
}

type gen struct {
	names   map[string]string // contract name -> Python name
	classes map[string]*class // by Python name
	inline  map[string]string // canonical inline schema -> Python name
	err     error
}

// pyName is the contract name without the decision engine's package prefix (DecideEvaluationRequest is
// EvaluationRequest); the other packages keep theirs (GateChange, ProvenanceVerdict).
func pyName(contractName string) string {
	return strings.TrimPrefix(contractName, "Decide")
}

var pyKeywords = map[string]bool{"False": true, "None": true, "True": true, "and": true, "as": true, "assert": true,
	"async": true, "await": true, "break": true, "class": true, "continue": true, "def": true, "del": true,
	"elif": true, "else": true, "except": true, "finally": true, "for": true, "from": true, "global": true,
	"if": true, "import": true, "in": true, "is": true, "lambda": true, "nonlocal": true, "not": true, "or": true,
	"pass": true, "raise": true, "return": true, "try": true, "while": true, "with": true, "yield": true}

var identRx = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

func attrName(j string) (string, error) {
	if !identRx.MatchString(j) {
		return "", fmt.Errorf("field %q is not a Python identifier", j)
	}
	if pyKeywords[j] || strings.HasPrefix(j, "_") {
		return j + "_", nil
	}
	return j, nil
}

// Models is _models.py for the contract.
func Models(contract []byte) ([]byte, error) {
	var d doc
	dec := json.NewDecoder(bytes.NewReader(contract))
	dec.UseNumber()
	if err := dec.Decode(&d); err != nil {
		return nil, fmt.Errorf("the contract: %w", err)
	}
	g := &gen{names: map[string]string{}, classes: map[string]*class{}, inline: map[string]string{}}
	seen := map[string]string{}
	for _, n := range sortedKeys(d.Components.Schemas) {
		p := pyName(n)
		if other, dup := seen[p]; dup {
			return nil, fmt.Errorf("contract schemas %s and %s are both Python class %s", other, n, p)
		}
		seen[p] = n
		g.names[n] = p
	}
	for _, n := range sortedKeys(d.Components.Schemas) {
		g.object(g.names[n], n, d.Components.Schemas[n])
	}
	// Operations, in path and method order.
	type op struct {
		id, method, path, auth, request, response string
		maxBody                                   int64
	}
	var ops []op
	for _, path := range sortedKeys(d.Paths) {
		for _, method := range sortedKeys(d.Paths[path]) {
			o := d.Paths[path][method]
			x := op{id: o.OperationID, method: strings.ToUpper(method), path: path, auth: o.Auth, maxBody: o.MaxBody}
			if o.RequestBody != nil {
				if s, ok := o.RequestBody.Content["application/json"]; ok {
					x.request = g.refName(s.Schema)
				}
			}
			for _, code := range sortedKeys(o.Responses) {
				if code[0] != '2' {
					continue
				}
				if s, ok := o.Responses[code].Content["application/json"]; ok && x.response == "" {
					x.response = g.responseName(s.Schema)
				}
			}
			ops = append(ops, x)
		}
	}
	if g.err != nil {
		return nil, g.err
	}

	var b strings.Builder
	b.WriteString(header + "\n")
	b.WriteString(`"""The core's request and answer types, generated from contract/clearance-core.json (info.version ` +
		d.Info.Version + `).

Each class is a dataclass with to_dict() and from_dict(data, strict=True) (_codec.Model). from_dict checks every
field's JSON type and, when strict, refuses a key the contract does not name. to_dict leaves out an optional field
that is None.
"""` + "\n\n")
	b.WriteString("from __future__ import annotations\n\n")
	b.WriteString("import dataclasses\nimport datetime\nfrom typing import Any, ClassVar\n\n")
	b.WriteString("from ._codec import Field, Model, Operation\n\n")
	b.WriteString("CONTRACT_VERSION = " + strconv.Quote(d.Info.Version) + "\n\n")
	b.WriteString("RECORD_KINDS: tuple[str, ...] = (" + pyStrings(d.RecordKinds) + ")\n")
	b.WriteString("\n__all__ = [\"CONTRACT_VERSION\", \"MODELS\", \"OPERATIONS\", \"RECORD_KINDS\"")
	for _, name := range sortedKeys(g.classes) {
		b.WriteString(", " + strconv.Quote(name))
	}
	b.WriteString("]\n")
	for _, name := range sortedKeys(g.classes) {
		c := g.classes[name]
		b.WriteString("\n\n@dataclasses.dataclass(kw_only=True, slots=True)\n")
		b.WriteString("class " + c.name + "(Model):\n")
		doc := "contract schema " + c.source
		if c.source == "" {
			doc = "an inline answer schema of the contract"
		}
		if c.strict {
			doc += " (a request type: unknown keys are refused by the core)"
		}
		b.WriteString("    \"\"\"" + strings.ToUpper(doc[:1]) + doc[1:] + ".\"\"\"\n\n")
		b.WriteString("    _STRICT: ClassVar[bool] = " + pyBool(c.strict) + "\n")
		b.WriteString("    _FIELDS: ClassVar[tuple[Field, ...]] = (\n")
		for _, f := range c.fields {
			b.WriteString("        Field(" + strconv.Quote(f.json) + ", " + strconv.Quote(f.attr) + ", " + f.desc + ", " +
				pyBool(f.required) + "),\n")
		}
		b.WriteString("    )\n\n")
		for _, f := range c.fields {
			if f.required {
				b.WriteString("    " + f.attr + ": " + f.typ + "\n")
			} else {
				b.WriteString("    " + f.attr + ": " + optional(f.typ) + " = None\n")
			}
		}
	}
	b.WriteString("\n\nMODELS: dict[str, type[Model]] = {\n")
	for _, name := range sortedKeys(g.classes) {
		b.WriteString("    " + strconv.Quote(name) + ": " + name + ",\n")
	}
	b.WriteString("}\n")
	b.WriteString("\nOPERATIONS: dict[str, Operation] = {\n")
	for _, o := range ops {
		b.WriteString("    " + strconv.Quote(o.id) + ": Operation(" + strconv.Quote(o.method) + ", " + strconv.Quote(o.path) +
			", " + strconv.Quote(o.auth) + ", " + strconv.FormatInt(o.maxBody, 10) + ", " + pyOptName(o.request) + ", " +
			pyOptName(o.response) + "),\n")
	}
	b.WriteString("}\n")
	return []byte(b.String()), nil
}

func pyOptName(n string) string {
	if n == "" {
		return "None"
	}
	return n
}

func pyBool(v bool) string {
	if v {
		return "True"
	}
	return "False"
}

func pyStrings(xs []string) string {
	q := make([]string, len(xs))
	for i, x := range xs {
		q[i] = strconv.Quote(x)
	}
	s := strings.Join(q, ", ")
	if len(xs) == 1 {
		s += ","
	}
	return s
}

func (g *gen) fail(err error) {
	if g.err == nil {
		g.err = err
	}
}

// object adds the dataclass for an object schema.
func (g *gen) object(name, source string, s schema) {
	if _, done := g.classes[name]; done {
		return
	}
	if t, _ := s["type"].(string); t != "object" {
		g.fail(fmt.Errorf("schema %s is not an object", source))
		return
	}
	c := &class{name: name, source: source}
	g.classes[name] = c
	c.strict = s["additionalProperties"] == false
	required := map[string]bool{}
	if rs, ok := s["required"].([]any); ok {
		for _, r := range rs {
			required[r.(string)] = true
		}
	}
	props, _ := s["properties"].(map[string]any)
	for _, j := range sortedKeys(props) {
		ps, _ := props[j].(map[string]any)
		typ, desc := g.typeOf(schema(ps), source+"."+j)
		attr, err := attrName(j)
		if err != nil {
			g.fail(fmt.Errorf("%s: %w", source, err))
		}
		c.fields = append(c.fields, pyField{json: j, attr: attr, typ: typ, desc: desc, required: required[j]})
	}
}

// typeOf is a property schema's Python annotation and its codec descriptor.
func (g *gen) typeOf(s schema, where string) (string, string) {
	if ref, ok := s["$ref"].(string); ok {
		n := g.refTarget(ref)
		return n, "(\"ref\", " + strconv.Quote(n) + ")"
	}
	if alts, ok := s["oneOf"].([]any); ok {
		if len(alts) == 2 {
			if null, _ := alts[1].(map[string]any); null["type"] == "null" {
				inner, _ := alts[0].(map[string]any)
				t, d := g.typeOf(schema(inner), where)
				return t + " | None", "(\"nullable\", " + d + ")"
			}
		}
		g.fail(fmt.Errorf("%s: a oneOf other than [schema, null]", where))
		return "Any", "(\"any\",)"
	}
	switch t := s["type"].(type) {
	case nil:
		if len(s) == 0 || (len(s) == 1 && s["description"] != nil) {
			return "Any", "(\"any\",)"
		}
	case []any:
		if len(t) == 2 && t[1] == "null" {
			inner := schema{"type": t[0]}
			if f, ok := s["format"]; ok {
				inner["format"] = f
			}
			typ, d := g.typeOf(inner, where)
			return typ + " | None", "(\"nullable\", " + d + ")"
		}
	case string:
		switch t {
		case "string":
			if s["format"] == "date-time" {
				return "datetime.datetime", "(\"datetime\",)"
			}
			return "str", "(\"str\",)"
		case "integer":
			return "int", "(\"int\",)"
		case "number":
			return "float", "(\"number\",)"
		case "boolean":
			return "bool", "(\"bool\",)"
		case "array":
			items, _ := s["items"].(map[string]any)
			typ, d := g.typeOf(schema(items), where+"[]")
			return "list[" + typ + "]", "(\"list\", " + d + ")"
		case "object":
			if ap, ok := s["additionalProperties"].(map[string]any); ok && s["properties"] == nil {
				typ, d := g.typeOf(schema(ap), where+"{}")
				return "dict[str, " + typ + "]", "(\"map\", " + d + ")"
			}
			if s["properties"] == nil {
				return "dict[str, Any]", "(\"map\", (\"any\",))"
			}
		}
	}
	g.fail(fmt.Errorf("%s: no Python type for schema %v", where, map[string]any(s)))
	return "Any", "(\"any\",)"
}

func (g *gen) refTarget(ref string) string {
	n := strings.TrimPrefix(ref, "#/components/schemas/")
	p, ok := g.names[n]
	if !ok {
		g.fail(fmt.Errorf("unknown $ref %s", ref))
	}
	return p
}

// refName is a request schema's class: a $ref, or "" for a body documented only in prose.
func (g *gen) refName(s schema) string {
	if ref, ok := s["$ref"].(string); ok {
		return g.refTarget(ref)
	}
	return ""
}

// responseName is an answer schema's class: a $ref, or an allOf of a $ref and an object adding fields, which
// becomes its own class "<Base>With<Field>..." (the gate's change with audit_seq: GateChangeWithAuditSeq).
func (g *gen) responseName(s schema) string {
	if n := g.refName(s); n != "" {
		return n
	}
	parts, ok := s["allOf"].([]any)
	if !ok || len(parts) != 2 {
		g.fail(fmt.Errorf("an answer schema that is neither a $ref nor allOf [$ref, object]: %v", map[string]any(s)))
		return ""
	}
	base, _ := parts[0].(map[string]any)
	ext, _ := parts[1].(map[string]any)
	baseName := g.refName(schema(base))
	baseSrc := strings.TrimPrefix(fmt.Sprint(base["$ref"]), "#/components/schemas/")
	canon, _ := json.Marshal(s)
	if n, done := g.inline[string(canon)]; done {
		return n
	}
	extProps, _ := ext["properties"].(map[string]any)
	name := baseName + "With"
	for _, k := range sortedKeys(extProps) {
		name += pascal(k)
	}
	// Merge: the base's fields and required, then the extension's.
	bc, ok := g.classes[baseName]
	if !ok {
		g.fail(fmt.Errorf("allOf base %s is not a generated class", baseSrc))
		return ""
	}
	merged := &class{name: name, strict: bc.strict}
	merged.fields = append(merged.fields, bc.fields...)
	required := map[string]bool{}
	if rs, ok := ext["required"].([]any); ok {
		for _, r := range rs {
			required[r.(string)] = true
		}
	}
	for _, j := range sortedKeys(extProps) {
		ps, _ := extProps[j].(map[string]any)
		typ, desc := g.typeOf(schema(ps), name+"."+j)
		attr, err := attrName(j)
		if err != nil {
			g.fail(err)
		}
		merged.fields = append(merged.fields, pyField{json: j, attr: attr, typ: typ, desc: desc, required: required[j]})
	}
	sort.SliceStable(merged.fields, func(i, j int) bool { return merged.fields[i].json < merged.fields[j].json })
	if _, clash := g.classes[name]; clash {
		g.fail(fmt.Errorf("inline class %s clashes with a contract schema", name))
		return ""
	}
	g.classes[name] = merged
	g.inline[string(canon)] = name
	return name
}

func pascal(s string) string {
	var b strings.Builder
	for _, part := range strings.FieldsFunc(s, func(r rune) bool { return r == '_' || r == '-' }) {
		b.WriteString(strings.ToUpper(part[:1]) + part[1:])
	}
	return b.String()
}

func sortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// optional is typ or None, once.
func optional(typ string) string {
	if strings.HasSuffix(typ, " | None") {
		return typ
	}
	return typ + " | None"
}
